const wb = $('Webhook').first()?.json?.body || {};
const min_apply_count = (wb.min_apply_count !== undefined) ? parseInt(wb.min_apply_count, 10) : ((wb.minApplyCount !== undefined) ? parseInt(wb.minApplyCount, 10) : 150);
const max_footer_days = (wb.max_footer_days !== undefined) ? parseInt(wb.max_footer_days, 10) : ((wb.maxFooterDays !== undefined) ? parseInt(wb.maxFooterDays, 10) : 29);

let listingItems = [];
try {
  listingItems = $('Apify List').all().map(i => i.json);
} catch (e) {
  listingItems = [];
}

listingItems = listingItems.filter(i => i && Object.keys(i).length > 0 && (i.companyName || i.jobId || i.error));

if (!listingItems || listingItems.length === 0 || listingItems[0]?.error || listingItems[0]?.statusCode >= 400) {
  const errMsg = listingItems?.[0]?.error || listingItems?.[0]?.message || 'Apify returned zero rows or failed for query';
  return [{
    json: {
      has_error: true,
      error: errMsg,
      has_survivors: false,
      jobIds: [],
      pass1_map: {},
      rows_listed: 0,
      job_ids_requested: 0,
      dropped: { consultant: 0, stale: 0, dedup: 0, no_name: 0, no_job_id: 0, intra_batch_duplicate: 0, below_floor: 0, velocity: 0 },
      apify_cost_estimate_usd: 0,
      min_apply_count,
      max_footer_days
    }
  }];
}

const norm = s => (s || '').toLowerCase()
  .replace(/\b(pvt|private|ltd|limited|llp|inc|co|company|industries|india)\b/gi, '')
  .replace(/[^a-z0-9]/g, '');

let existing = [];
try {
  existing = $('Existing Leads').all().map(i => i.json);
} catch (e) {
  existing = [];
}
const seen = new Set(existing.map(e => norm(e.company_name)).filter(Boolean));

const parseFooterDays = (fl) => {
  const s = String(fl || '').trim().toLowerCase();
  if (!s || s === 'just now' || s === 'today') return 0;
  if (s === 'yesterday' || s === '1 day ago' || s === '1 days ago') return 1;
  const m = s.match(/^(\d+)\s+day/);
  if (m) return parseInt(m[1], 10);
  if (s.includes('30+')) return 30;
  return 30;
};

let dropped_consultant = 0;
let dropped_stale = 0;
let dropped_dedup = 0;
let dropped_no_name = 0;
let dropped_no_job_id = 0;
let dropped_intra_batch_duplicate = 0;
const survivingJobIds = [];
const pass1_map = {};

for (const r of listingItems) {
  if (r.consultant) {
    dropped_consultant++;
    continue;
  }
  const fDays = parseFooterDays(r.footerLabel);
  if (fDays > max_footer_days || String(r.footerLabel || '').includes('30+')) {
    dropped_stale++;
    continue;
  }
  const name = r.companyName;
  if (!name || !String(name).trim()) {
    dropped_no_name++;
    continue;
  }
  const n = norm(name);
  if (!n || seen.has(n)) {
    dropped_dedup++;
    continue;
  }
  const jId = String(r.jobId || '').trim();
  if (!jId) {
    dropped_no_job_id++;
    continue;
  }
  if (pass1_map[jId]) {
    dropped_intra_batch_duplicate++;
    continue;
  }
  survivingJobIds.push(jId);
  pass1_map[jId] = {
    jobId: jId,
    companyName: name,
    norm: n,
    location: r.location || '',
    footerDays: fDays,
    footerLabel: r.footerLabel || ''
  };
}

const has_survivors = survivingJobIds.length > 0;
return [{
  json: {
    has_error: false,
    has_survivors,
    jobIds: survivingJobIds,
    pass1_map,
    rows_listed: listingItems.length,
    job_ids_requested: survivingJobIds.length,
    dropped: {
      consultant: dropped_consultant,
      stale: dropped_stale,
      dedup: dropped_dedup,
      no_name: dropped_no_name,
      no_job_id: dropped_no_job_id,
      intra_batch_duplicate: dropped_intra_batch_duplicate,
      below_floor: 0,
      velocity: 0
    },
    min_apply_count,
    max_footer_days
  }
}];

const prep = $('Pass 1 Filter & Dedup').first().json;
const p1_map = prep.pass1_map || {};

let enrichedItems = [];
try {
  enrichedItems = $('Apify Enrich').all().map(i => i.json);
} catch (e) {
  enrichedItems = [];
}

enrichedItems = enrichedItems.filter(i => i && Object.keys(i).length > 0 && (i.jobId || i.companyName || i.error));

const norm = s => (s || '').toLowerCase()
  .replace(/\b(pvt|private|ltd|limited|llp|inc|co|company|industries|india)\b/gi, '')
  .replace(/[^a-z0-9]/g, '');

const history_rows = [];

for (const r of enrichedItems) {
  const jId = String(r.jobId || '').trim();
  if (!jId) continue;
  const p1 = p1_map[jId] || {};
  const compName = p1.companyName || r.companyName || '';
  const n = p1.norm || norm(compName);
  const applyCount = parseInt(r.applyCount || 0, 10);
  history_rows.push({
    job_id: jId,
    company_key: n,
    apply_count: String(applyCount)
  });
}

return [{
  json: {
    history_rows,
    has_history: history_rows.length > 0
  }
}];

