INSERT INTO job_apply_history (job_id, company_key, apply_count, seen_at)
SELECT r.job_id, r.company_key, NULLIF(r.apply_count,'')::int, now()
FROM jsonb_to_recordset($1::jsonb) AS r(job_id text, company_key text, apply_count text);

