const prep = $('Pass 1 Filter & Dedup').first().json;
const p1_map = prep.pass1_map || {};

let enrichedItems = [];
try {
  enrichedItems = $('Apify Enrich').all().map(i => i.json);
} catch (e) {
  enrichedItems = [];
}

enrichedItems = enrichedItems.filter(i => i && Object.keys(i).length > 0 && (i.jobId || i.companyName || i.error));

if (!enrichedItems || enrichedItems.length === 0 || enrichedItems[0]?.error || enrichedItems[0]?.statusCode >= 400) {
  const cost = Number(((prep.rows_listed * 0.0005) + 0.00005).toFixed(5));
  const errMsg = enrichedItems?.[0]?.error || enrichedItems?.[0]?.message || 'Apify enrichment call failed or returned zero rows';
  return [{
    json: {
      error: errMsg,
      meta: {
        rows_listed: prep.rows_listed,
        job_ids_requested: prep.job_ids_requested,
        rows_enriched: 0,
        dropped: prep.dropped,
        apify_cost_estimate_usd: cost
      }
    }
  }];
}

const norm = s => (s || '').toLowerCase()
  .replace(/\b(pvt|private|ltd|limited|llp|inc|co|company|industries|india)\b/gi, '')
  .replace(/[^a-z0-9]/g, '');

const parseFooterDays = (fl) => {
  const s = String(fl || '').trim().toLowerCase();
  if (!s || s === 'just now' || s === 'today') return 0;
  if (s === 'yesterday' || s === '1 day ago' || s === '1 days ago') return 1;
  const m = s.match(/^(\d+)\s+day/);
  if (m) return parseInt(m[1], 10);
  if (s.includes('30+')) return 30;
  return 30;
};

const getCreatedAgeDays = (createdDate, fallbackDays) => {
  if (!createdDate) return fallbackDays !== undefined ? fallbackDays : 0;
  const d = new Date(createdDate);
  if (isNaN(d.getTime())) return fallbackDays !== undefined ? fallbackDays : 0;
  const diffMs = Date.now() - d.getTime();
  return Math.max(0, Math.floor(diffMs / (1000 * 60 * 60 * 24)));
};

let dropped_velocity = 0;
const grouped = {};

for (const r of enrichedItems) {
  const jId = String(r.jobId || '').trim();
  const p1 = p1_map[jId] || {};

  const compName = p1.companyName || r.companyName || '';
  const n = p1.norm || norm(compName);
  if (!n) continue;

  const fDays = p1.footerDays !== undefined ? p1.footerDays : parseFooterDays(r.footerLabel);
  const applyCount = parseInt(r.applyCount || 0, 10);
  const createdAgeDays = getCreatedAgeDays(r.createdDate, fDays);
  const velocity = applyCount / Math.max(1, createdAgeDays);

  // Velocity guard: drop when listing older than 90 days AND velocity < 3
  if (createdAgeDays > 90 && velocity < 3) {
    dropped_velocity++;
    continue;
  }

  const city = p1.location || (r.locations && r.locations[0] && r.locations[0].label) || r.location || '';

  if (!grouped[n]) {
    grouped[n] = {
      company_name: compName,
      norm: n,
      city: city,
      industry: r.industry || r.companyIndustry || '',
      apply_count_total: 0,
      roles_count: 0,
      role_titles: [],
      job_ids: [],
      footer_days_min: Infinity,
      created_age_days_min: Infinity,
      velocity_max: 0,
      company_website: r.companyWebsite || '',
      emails: [],
      phones: [],
      walkin: false
    };
  }

  const g = grouped[n];
  g.apply_count_total += applyCount;
  g.roles_count += 1;

  if (!g.city && city) g.city = city;
  if (!g.industry && (r.industry || r.companyIndustry)) g.industry = r.industry || r.companyIndustry;

  const title = (r.title || r.jobTitle || '').trim();
  if (title && !g.role_titles.includes(title)) {
    g.role_titles.push(title);
  }

  if (jId && !g.job_ids.includes(jId)) {
    g.job_ids.push(jId);
  }

  if (fDays < g.footer_days_min) {
    g.footer_days_min = fDays;
  }

  if (createdAgeDays < g.created_age_days_min) {
    g.created_age_days_min = createdAgeDays;
  }

  const velRounded = Number(velocity.toFixed(1));
  if (velRounded > g.velocity_max) {
    g.velocity_max = velRounded;
  }

  if (!g.company_website && r.companyWebsite) {
    g.company_website = r.companyWebsite;
  }

  if (r.extractedEmails && Array.isArray(r.extractedEmails)) {
    for (const em of r.extractedEmails) {
      if (em && !g.emails.includes(em)) g.emails.push(em);
    }
  } else if (r.contactEmail && !g.emails.includes(r.contactEmail)) {
    g.emails.push(r.contactEmail);
  }

  if (r.extractedPhones && Array.isArray(r.extractedPhones)) {
    for (const ph of r.extractedPhones) {
      if (ph && !g.phones.includes(ph)) g.phones.push(ph);
    }
  } else if (r.extractedPhoneNumbers && Array.isArray(r.extractedPhoneNumbers)) {
    for (const ph of r.extractedPhoneNumbers) {
      if (ph && !g.phones.includes(ph)) g.phones.push(ph);
    }
  } else if (r.contactPhone && !g.phones.includes(r.contactPhone)) {
    g.phones.push(r.contactPhone);
  }

  if (r.isWalkin || r.walkin || r.walkIn || r.walkinJob) {
    g.walkin = true;
  }
}

let dropped_below_floor = 0;
const survivingCompanies = [];

for (const comp of Object.values(grouped)) {
  if (comp.footer_days_min === Infinity) comp.footer_days_min = 0;
  if (comp.created_age_days_min === Infinity) comp.created_age_days_min = 0;

  if (comp.apply_count_total < prep.min_apply_count) {
    dropped_below_floor++;
    continue;
  }
  survivingCompanies.push(comp);
}

const apify_cost_estimate_usd = Number(((prep.rows_listed * 0.0005) + (enrichedItems.length * 0.002) + 0.0001).toFixed(5));

const meta = {
  rows_listed: prep.rows_listed,
  job_ids_requested: prep.job_ids_requested,
  rows_enriched: enrichedItems.length,
  dropped: {
    consultant: prep.dropped.consultant,
    stale: prep.dropped.stale,
    dedup: prep.dropped.dedup,
    no_name: prep.dropped.no_name,
    no_job_id: prep.dropped.no_job_id,
    intra_batch_duplicate: prep.dropped.intra_batch_duplicate,
    below_floor: dropped_below_floor,
    velocity: dropped_velocity
  },
  apify_cost_estimate_usd
};

// Defect 1 fix: Zero companies is NEVER an empty success
if (survivingCompanies.length === 0) {
  const errorMsg = `0 of ${prep.rows_listed} rows survived: ${prep.dropped.stale} stale, ${prep.dropped.dedup} dedup, ${dropped_below_floor} below volume floor (<${prep.min_apply_count}), ${dropped_velocity} velocity guard`;
  return [{
    json: {
      error: errorMsg,
      meta
    }
  }];
}

const output = survivingCompanies.map(c => ({ json: c }));
output.push({ json: { meta } });
return output;

const prep = $('Pass 1 Filter & Dedup').first().json;
const cost = Number(((prep.rows_listed * 0.0005) + 0.00005).toFixed(5));

const droppedDetails = [];
if (prep.dropped?.stale) droppedDetails.push(`${prep.dropped.stale} stale`);
if (prep.dropped?.dedup) droppedDetails.push(`${prep.dropped.dedup} dedup`);
if (prep.dropped?.consultant) droppedDetails.push(`${prep.dropped.consultant} consultant`);
if (prep.dropped?.no_name) droppedDetails.push(`${prep.dropped.no_name} no name`);
if (prep.dropped?.no_job_id) droppedDetails.push(`${prep.dropped.no_job_id} no job ID`);
if (prep.dropped?.intra_batch_duplicate) droppedDetails.push(`${prep.dropped.intra_batch_duplicate} intra-batch duplicates`);

const errorMsg = prep.error || `0 of ${prep.rows_listed} rows survived pass 1: ${droppedDetails.join(', ') || 'all rows filtered'}`;

return [{
  json: {
    error: errorMsg,
    meta: {
      rows_listed: prep.rows_listed,
      job_ids_requested: 0,
      rows_enriched: 0,
      dropped: prep.dropped,
      apify_cost_estimate_usd: cost
    }
  }
}];
